SELECT name FROM products WHERE category = 'Peryferia' AND price > 100;
SELECT name FROM products WHERE category = 'Komputery' OR price < 20;
SELECT name FROM products WHERE NOT category = 'Peryferia';

SELECT name FROM products WHERE name LIKE 'K%'; -- zaczyna sie na K
SELECT name FROM products WHERE name LIKE '%top%'; -- zawiera "top" gdziekolwiek

// Case-insensitive, przenosnie (bez ILIKE, ktore NIE jest standardem SQL):
SELECT name FROM products WHERE LOWER(name) LIKE LOWER('%laptop%');
